import unittest
from candidate import string_xor

class TestStringXor(unittest.TestCase):
    def test_normal_equal_length_binary(self):
        self.assertEqual(string_xor('010', '110'), '100')

    def test_normal_equal_length_all_ones(self):
        self.assertEqual(string_xor('1111', '1111'), '0000')

    def test_normal_equal_length_all_zeros(self):
        self.assertEqual(string_xor('0000', '0000'), '0000')

    def test_truncate_longer_input_a(self):
        self.assertEqual(string_xor('101010', '0101'), '1111')
        self.assertEqual(len(string_xor('101010', '0101')), 4)

    def test_truncate_longer_input_b(self):
        self.assertEqual(string_xor('0101', '101010'), '1111')
        self.assertEqual(len(string_xor('0101', '101010')), 4)

    def test_both_empty_strings(self):
        self.assertEqual(string_xor('', ''), '')

    def test_one_empty_first(self):
        self.assertEqual(string_xor('', '1010'), '')

    def test_one_empty_second(self):
        self.assertEqual(string_xor('1010', ''), '')

    def test_none_input_raises_type_error_first(self):
        with self.assertRaises(TypeError):
            string_xor(None, '1010')

    def test_none_input_raises_type_error_second(self):
        with self.assertRaises(TypeError):
            string_xor('1010', None)

    def test_integer_input_raises_type_error_first(self):
        with self.assertRaises(TypeError):
            string_xor(1010, '1010')

    def test_integer_input_raises_type_error_second(self):
        with self.assertRaises(TypeError):
            string_xor('1010', 1010)

    def test_non_binary_characters_xor(self):
        self.assertEqual(string_xor('2a', 'ab'), '11')
        self.assertEqual(string_xor('a', 'b'), '1')

    def test_unicode_characters_xor(self):
        self.assertEqual(string_xor('ä', 'ü'), '1')
        self.assertEqual(string_xor('ä', 'ä'), '0')

    def test_xor_is_pure_function(self):
        a = '0101'
        b = '1010'
        result1 = string_xor(a, b)
        result2 = string_xor(a, b)
        self.assertEqual(result1, result2)
        self.assertNotEqual(id(result1), id(result2))

    def test_xor_single_character(self):
        self.assertEqual(string_xor('0', '1'), '1')
        self.assertEqual(string_xor('1', '1'), '0')

    def test_xor_long_strings(self):
        a = '1' * 10000
        b = '0' * 10000
        expected = '1' * 10000
        self.assertEqual(string_xor(a, b), expected)

    def test_xor_mixed_length_with_non_binary(self):
        self.assertEqual(string_xor('1102', '1100'), '0010')

    def test_xor_result_length_minimum(self):
        a = '1101'
        b = '001'
        result = string_xor(a, b)
        self.assertEqual(len(result), min(len(a), len(b)))
        self.assertEqual(result, '111')

if __name__ == '__main__':
    unittest.main()
